import embeddingsFile from '../data/embeddings.json'

// Everything the chat knows lives in embeddings.json (generated by `npm run embed`), so the
// server only needs this file: no database and no extra reads at request time.
const index = embeddingsFile.chunks as {
     title: string
     category: string
     content: string
     embedding: number[]
}[]

export interface RetrievedChunk {
     title: string
     category: string
     content: string
     score: number
}

/** Vectors are normalized, so the dot product equals cosine similarity. */
export function search(queryEmbedding: number[], topK = 5): RetrievedChunk[] {
     return index
          .map(({ embedding, ...chunk }) => {
               let score = 0
               for (let i = 0; i < embedding.length; i++) {
                    score += embedding[i] * queryEmbedding[i]
               }
               return { ...chunk, score }
          })
          .sort((a, b) => b.score - a.score)
          .slice(0, topK)
}
